descriptor.templateCss:
.tm-hr-card {
  display: flex;
  flex-direction: column;
  background: #0f172a;
  border: 1px solid #1e293b;
  border-radius: 10px;
  padding: 16px 20px;
  color: #f8fafc;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
}
.hr-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid #1e293b;
  margin-bottom: 12px;
}
.hr-title {
  font-size: 15px;
  font-weight: 700;
  color: #38bdf8;
  letter-spacing: 0.01em;
}
.hr-sub {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 2px;
}
.hr-overall-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 20px;
  letter-spacing: 0.03em;
}
.hr-overall-badge.normal {
  background: rgba(34, 197, 94, 0.15);
  color: #4ade80;
  border: 1px solid rgba(34, 197, 94, 0.35);
}
.hr-overall-badge.warning {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.35);
}
.hr-overall-badge.alarm {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.35);
}
.hr-table-wrap {
  flex: 1;
  overflow-y: auto;
}
.hr-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 4px;
}
.hr-table th {
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 6px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.hr-row {
  background: rgba(30, 41, 59, 0.45);
  border-radius: 6px;
  transition: background 0.2s;
}
.hr-row:hover {
  background: rgba(30, 41, 59, 0.7);
}
.hr-cell {
  padding: 8px 10px;
  vertical-align: middle;
}
.hr-channel {
  display: flex;
  align-items: center;
  gap: 8px;
}
.hr-tag {
  font-size: 11px;
  font-weight: 700;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.25);
  padding: 2px 6px;
  border-radius: 4px;
  font-family: monospace;
}
.hr-name {
  font-size: 12px;
  color: #e2e8f0;
  font-weight: 500;
}
.hr-val {
  font-size: 13px;
  font-weight: 700;
  color: #00e5ff;
  font-family: monospace;
  text-align: right;
}
.hr-lim {
  font-size: 12px;
  font-weight: 600;
  color: #94a3b8;
  font-family: monospace;
  text-align: right;
}
.hr-lim.warn { color: #f59e0b; }
.hr-lim.alarm { color: #ef4444; }
.hr-bar-container {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.hr-bar-wrap {
  height: 6px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 3px;
  overflow: hidden;
  position: relative;
}
.hr-bar-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease, background-color 0.3s ease;
}
.hr-bar-fill.normal { background: linear-gradient(90deg, #10b981 0%, #34d399 100%); }
.hr-bar-fill.warning { background: linear-gradient(90deg, #f59e0b 0%, #fbbf24 100%); }
.hr-bar-fill.alarm { background: linear-gradient(90deg, #ef4444 0%, #f87171 100%); }
.hr-bar-text {
  font-size: 10px;
  color: #cbd5e1;
  font-weight: 500;
}
.hr-status-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 10px;
  text-align: center;
  display: inline-block;
}
.hr-status-badge.normal {
  background: rgba(34, 197, 94, 0.15);
  color: #4ade80;
  border: 1px solid rgba(34, 197, 94, 0.35);
}
.hr-status-badge.warning {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.35);
}
.hr-status-badge.alarm {
  background: rgba(239, 68, 68, 0.2);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.4);
}

descriptor.controllerScript:
self.onInit = function () {
  var root = self.ctx.$container ? self.ctx.$container[0] : (self.ctx.container || document.querySelector('.tm-hr-card'));
  if (!root) return;

  var tbody = root.querySelector('#hr-tbody');
  var overall = root.querySelector('#hr-overall-status');

  self.ctx.channels = [
    { key: 'XT_600', name: 'Turbine Bearing Radial Vib', unit: 'mm/s', decimals: 3, warn: 4.5, alarm: 6.0, val: 0.55 },
    { key: 'XT_604', name: 'Gearbox Pinion Bearing Vib', unit: 'mm/s', decimals: 3, warn: 4.0, alarm: 5.5, val: 0.64 },
    { key: 'ZT_600', name: 'Thrust Bearing Axial Position', unit: 'mils', decimals: 2, warn: 3.0, alarm: 4.5, val: -0.88, isAbs: true },
    { key: 'PYRO_T', name: 'Turbine Rotor Core Pyrometer', unit: '°C', decimals: 1, warn: 330, alarm: 350, val: 24.5 },
    { key: 'PYRO_GB', name: 'Gearbox High-Speed Temp', unit: '°C', decimals: 1, warn: 200, alarm: 220, val: 24.5 },
    { key: 'TT_109A', name: 'Main Steam Admission Temp', unit: '°C', decimals: 1, warn: 280, alarm: 310, val: 262.1 },
    { key: 'PT_109A', name: 'Main Steam Header Pressure', unit: 'bar', decimals: 2, warn: 35.0, alarm: 38.0, val: 32.22 },
    { key: 'TURBINE_SPEED_RPM', name: 'Turbine Rotor Speed', unit: 'RPM', decimals: 0, warn: 12000, alarm: 13500, val: 10500 }
  ];

  self.ctx.updateHeadroomUI = function () {
    if (!tbody) return;
    tbody.innerHTML = '';
    var maxSeverity = 'normal';

    self.ctx.channels.forEach(function (ch) {
      var val = ch.val;
      var effVal = ch.isAbs ? Math.abs(val) : val;
      var trip = ch.alarm;
      var warn = ch.warn;

      var headroomPct = Math.max(0, Math.min(100, Math.round(((trip - effVal) / trip) * 100)));
      var status = 'normal';
      if (effVal >= trip) {
        status = 'alarm';
        maxSeverity = 'alarm';
      } else if (effVal >= warn) {
        status = 'warning';
        if (maxSeverity !== 'alarm') maxSeverity = 'warning';
      }

      var tr = document.createElement('tr');
      tr.className = 'hr-row';
      tr.innerHTML = [
        '<td class="hr-cell"><div class="hr-channel"><span class="hr-tag">' + ch.key + '</span><span class="hr-name">' + ch.name + '</span></div></td>',
        '<td class="hr-cell hr-val">' + val.toFixed(ch.decimals) + ' <span style="font-size:10px; color:#94a3b8;">' + ch.unit + '</span></td>',
        '<td class="hr-cell hr-lim warn">' + warn.toFixed(ch.decimals > 1 ? 1 : 0) + '</td>',
        '<td class="hr-cell hr-lim alarm">' + trip.toFixed(ch.decimals > 1 ? 1 : 0) + '</td>',
        '<td class="hr-cell"><div class="hr-bar-container"><div class="hr-bar-wrap"><div class="hr-bar-fill ' + status + '" style="width:' + headroomPct + '%;"></div></div><div class="hr-bar-text">' + headroomPct + '% safe headroom</div></div></td>',
        '<td class="hr-cell" style="text-align:center;"><span class="hr-status-badge ' + status + '">' + status.toUpperCase() + '</span></td>'
      ].join('');
      tbody.appendChild(tr);
    });

    if (overall) {
      if (maxSeverity === 'alarm') {
        overall.className = 'hr-overall-badge alarm';
        overall.textContent = '● CRITICAL: CHANNEL BREACHED ALARM SETPOINT';
      } else if (maxSeverity === 'warning') {
        overall.className = 'hr-overall-badge warning';
        overall.textContent = '▲ WARNING: CHANNEL APPROACHING TRIP LIMIT';
      } else {
        overall.className = 'hr-overall-badge normal';
        overall.textContent = '● ALL 8 CHANNELS NOMINAL (SAFE HEADROOM > 20%)';
      }
    }
  };

  // Listen for dynamic threshold updates
  window.addEventListener('tb_thresholds_updated', function (e) {
    if (e.detail) {
      var d = e.detail;
      self.ctx.channels.forEach(function (ch) {
        if (d['threshold_' + ch.key + '_warn'] !== undefined) ch.warn = d['threshold_' + ch.key + '_warn'];
        if (d['threshold_' + ch.key + '_alarm'] !== undefined) ch.alarm = d['threshold_' + ch.key + '_alarm'];
      });
      self.ctx.updateHeadroomUI();
    }
  });

  self.ctx.updateHeadroomUI();
};

self.onDataUpdated = function () {
  if (!self.ctx.data || !self.ctx.channels) return;
  self.ctx.data.forEach(function (ds) {
    if (ds && ds.data && ds.data.length > 0) {
      var lastVal = Number(ds.data[ds.data.length - 1][1]);
      var keyName = ds.dataKey ? ds.dataKey.name : '';
      self.ctx.channels.forEach(function (ch) {
        if (ch.key === keyName && !isNaN(lastVal)) {
          ch.val = lastVal;
        }
      });
    }
  });
  if (self.ctx.updateHeadroomUI) {
    self.ctx.updateHeadroomUI();
  }
};

self.onDestroy = function () {};
